        static RoomModuleData New(string id, ZoneTheme theme, int w, int d, ZoneHeight height, float weight, int maxPerRun, float waterY)
        {
            var m = new RoomModuleData
            {
                width = w, depth = d, height = height, theme = theme, weight = weight, allowRotate = false, minTier = 0, maxTier = 9,
                placement = ModulePlacement.Room, fill = ModuleFill.None, columns = ModuleColumns.None,
            };
            m.Normalize();
            m.weight = weight;
            var skin = PoolRules.Default(theme).Clone();
            skin.waterY = waterY;
            skin.maxPerRun = maxPerRun;
            skin.cells = new ModuleCell[w * d];
            for (var k = 0; k < skin.cells.Length; k++) skin.cells[k] = PoolRules.DefaultCell(theme);
            skin.standIns = new ModuleStandIn[0];
            m.pool = skin;
            return m;
        }

        static void Keep(RoomModuleData m, string id)
        {
            made[id] = m;
        }

        static void Skin(RoomModuleData m, PoolCeiling ceiling, PoolLampKit lampKit, PoolUpper upper, float tileTop)
        {
            m.pool.ceiling = ceiling;
            m.pool.lampKit = lampKit;
            m.pool.upper = upper;
            m.pool.tileTop = tileTop;
            m.pool.bandLow = m.pool.bandHigh = 0f;
            m.pool.bandOnFloor = false;
            if (m.theme == ZoneTheme.PoolLevel) { m.pool.bandLow = .02f; m.pool.bandHigh = .32f; m.pool.bandOnFloor = true; }
        }

        static void Band(RoomModuleData m, float low, float high, bool onFloor)
        {
            m.pool.bandLow = low;
            m.pool.bandHigh = high;
            m.pool.bandOnFloor = onFloor;
        }

        // A water rect, in order (later over earlier): floor a at the rect's south edge to b at its north edge (a slope along +Z).
        static void Rect(RoomModuleData m, int x0, int z0, int w, int d, CellWater water, float a, float b, float waterY, bool beach)
        {
            var cs = MapGrid.CellSize;
            var span = d * cs;
            var slope = span > 0f ? (b - a) / span : 0f;
            for (var j = z0; j < z0 + d && j < m.depth; j++)
            for (var i = x0; i < x0 + w && i < m.width; i++)
            {
                if (i < 0 || j < 0) continue;
                var c = new ModuleCell { water = water, beach = beach, waterY = water == CellWater.Ankle || water == CellWater.Wade ? waterY : 0f };
                c.floorY = a + slope * ((j - z0) * cs + cs * .5f);
                c.slopeZ = slope;
                m.pool.cells[i + j * m.width] = c;
            }
        }

        static void Slope(RoomModuleData m, int i, int j, CellWater water, float a, float b, float waterY, bool beach)
        {
            var cs = MapGrid.CellSize;
            var c = new ModuleCell { water = water, beach = beach, waterY = water == CellWater.Ankle || water == CellWater.Wade ? waterY : 0f };
            c.floorY = (a + b) * .5f;
            c.slopeZ = (b - a) / cs;
            m.pool.cells[i + j * m.width] = c;
        }

        static void Stair(RoomModuleData m, int i, int j, CellWater water, int dir, float floorY, float from, int risers, float rise, float run, float waterY)
        {
            var c = new ModuleCell
            {
                water = water, floorY = floorY, connector = CellConnector.Stair, stairDir = (byte)dir, stairRisers = (byte)risers,
                stairFrom = from, stairRise = rise, stairRun = run,
                waterY = water == CellWater.Ankle || water == CellWater.Wade ? waterY : 0f,
            };
            m.pool.cells[i + j * m.width] = c;
        }

        static void Edge(RoomModuleData m, ModuleSide side, int index, ModuleEdge kind, float width, PoolEdgeStyle style, float crown, int trim)
        {
            if (side == ModuleSide.South) m.south[index] = kind;
            else if (side == ModuleSide.North) m.north[index] = kind;
            else if (side == ModuleSide.West) m.west[index] = kind;
            else m.east[index] = kind;
            if (width <= 0f && style == PoolEdgeStyle.None) return;
            var list = new List<ModuleEdgeRecord>(m.edgeRecords ?? new ModuleEdgeRecord[0]);
            list.Add(new ModuleEdgeRecord { side = side, index = index, archWidth = width, style = style, crown = crown, trim = (byte)trim });
            m.edgeRecords = list.ToArray();
        }

        static void Column(RoomModuleData m, int x, int y)
        {
            m.columns = ModuleColumns.Custom;
            var list = new List<ModuleColumn>(m.customColumns ?? new ModuleColumn[0]);
            list.Add(new ModuleColumn { x = x, y = y, large = false });
            m.customColumns = list.ToArray();
        }

        static void StandIn(RoomModuleData m, string kit, float x, float z, float y, float yaw, float length, bool collider, bool fromBase)
        {
            var list = new List<ModuleStandIn>(m.pool.standIns ?? new ModuleStandIn[0]);
            list.Add(new ModuleStandIn { kit = kit, x = x, z = z, y = y, yaw = yaw, length = length, collider = collider, fromBase = fromBase });
            m.pool.standIns = list.ToArray();
        }
    }
}
